/**
 * Update Supplier.
 *
 * @export
 * @async
 * @param {Request} req
 * @param {Response} res
 * @returns {unknown}
 */
export const update = async (req: Request, res: Response) => {
  const { body }: { body: bookcarsTypes.UpdateSupplierPayload } = req
  const { _id } = body

  try {
    if (!helper.isValidObjectId(_id)) {
      throw new Error('body._id is not valid')
    }

    // begin of security check
    const sessionUserId = req.user?._id
    const sessionUser = await User.findById(sessionUserId)
    const isAdmin = !!sessionUser && sessionUser?.type === bookcarsTypes.UserType.Admin
    if (!sessionUser || sessionUser.type === bookcarsTypes.UserType.User || (sessionUser.type === bookcarsTypes.UserType.Supplier && sessionUserId !== _id)) {
      logger.error(`[supplier.update] Unauthorized attempt to update supplier ${_id} by user ${sessionUserId}`)
      res.status(403).send('Forbidden: You cannot update supplier information')
      return
    }
    if (
      !isAdmin
      && restrictedSupplierFields.some((field) => Object.prototype.hasOwnProperty.call(body, field))
    ) {
      logger.error(`[supplier.update] Supplier ${sessionUserId} attempted to update restricted fields for supplier ${_id}`)
      res.status(403).send('Forbidden: You cannot update restricted supplier information')
      return
    }
    // end of security check

    const supplier = await User.findById(_id)

    if (supplier) {
      const {
        fullName,
        phone,
        location,
        bio,
        payLater,
        licenseRequired,
        minimumRentalDays,
        priceChangeRate,
        supplierCarLimit,
        notifyAdminOnNewCar,
        blacklisted,
      } = body
      supplier.fullName = fullName
      supplier.phone = phone
      supplier.location = location
      supplier.bio = bio
      supplier.payLater = payLater
      supplier.licenseRequired = licenseRequired
      supplier.minimumRentalDays = minimumRentalDays
      supplier.priceChangeRate = priceChangeRate
      if (isAdmin) {
        supplier.supplierCarLimit = supplierCarLimit
        supplier.notifyAdminOnNewCar = notifyAdminOnNewCar
        supplier.blacklisted = !!blacklisted
      }

      await supplier.save()
      res.json({
        _id,
        fullName: supplier.fullName,
        phone: supplier.phone,
        location: supplier.location,
        bio: supplier.bio,
        avatar: supplier.avatar,
        payLater: supplier.payLater,
        contracts: supplier.contracts,
        minimumRentalDays: supplier.minimumRentalDays,
        licenseRequired: supplier.licenseRequired,
        priceChangeRate: supplier.priceChangeRate,
        supplierCarLimit: supplier.supplierCarLimit,
        notifyAdminOnNewCar: supplier.notifyAdminOnNewCar,
        blacklisted: supplier.blacklisted,
      })
      return
    }
    logger.error('[supplier.update] Supplier not found:', _id)
    res.sendStatus(204)
  } catch (err) {
    logger.error(`[supplier.update] ${i18n.t('ERROR')} ${_id}`, err)
    res.status(400).send(i18n.t('ERROR') + err)
  }
}

/**
 * Delete Supplier by ID.
 *
 * @export
 * @async
 * @param {Request} req
 * @param {Response} res
 * @returns {unknown}
 */
export const deleteSupplier = async (req: Request, res: Response) => {
  const { id } = req.params

  try {
    // begin of security check
    const sessionUserId = req.user?._id
    const sessionUser = await User.findById(sessionUserId)
    if (!sessionUser || sessionUser.type != bookcarsTypes.UserType.Admin) {
      logger.error(`[supplier.delete] Unauthorized attempt to delete supplier ${id} by user ${sessionUserId}`)
      res.status(403).send('Forbidden: You cannot delete supplier')
      return
    }
    // end of security check

    const supplier = await User.findById(id)
    if (supplier) {
      await User.deleteOne({ _id: id })

      if (supplier.avatar) {
        const avatar = path.join(env.CDN_USERS, supplier.avatar)
        if (await helper.pathExists(avatar)) {
          await asyncFs.unlink(avatar)
        }
      }

      if (supplier.contracts && supplier.contracts.length > 0) {
        for (const contract of supplier.contracts) {
          if (contract.file) {
            const file = path.join(env.CDN_CONTRACTS, contract.file)
            if (await helper.pathExists(file)) {
              await asyncFs.unlink(file)
            }
          }
        }
      }

      await NotificationCounter.deleteMany({ user: id })
      await Notification.deleteMany({ user: id })
      const additionalDrivers = (
        await Booking
          .find(
            { supplier: id, _additionalDriver: { $ne: null } },
          )
          .select('_additionalDriver -_id')
          .lean()
      ).map((b) => b._additionalDriver)
      await AdditionalDriver.deleteMany({ _id: { $in: additionalDrivers } })
      await Booking.deleteMany({ supplier: id })
      const cars = await Car.find({ supplier: id })
      await Car.deleteMany({ supplier: id })
      for (const car of cars) {
        if (car.dateBasedPrices?.length > 0) {
          await DateBasedPrice.deleteMany({ _id: { $in: car.dateBasedPrices } })
        }

        if (car.image) {
          const image = path.join(env.CDN_CARS, car.image)
          if (await helper.pathExists(image)) {
            await asyncFs.unlink(image)
          }
        }
      }
    } else {
      res.sendStatus(204)
      return
    }
    res.sendStatus(200)
  } catch (err) {
    logger.error(`[supplier.delete] ${i18n.t('ERROR')} ${id}`, err)
    res.status(400).send(i18n.t('ERROR') + err)
  }
}

