            fullName: { $first: '$fullName' },
            avatar: { $first: '$avatar' },
            carCount: { $sum: { $cond: [{ $ifNull: ['$car', false] }, 1, 0] } },
          },
        },
        {
          $facet: {
            resultData: [{ $sort: { fullName: 1, _id: 1 } }, { $skip: (page - 1) * size }, { $limit: size }],
            pageInfo: [
              {
                $count: 'totalRecords',
              },
            ],
